public enum EnabledUnion: Codable {
    case bool(Bool)
    case enumeration(EnabledEnum)

    public init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let x = try? container.decode(Bool.self) {
            self = .bool(x)
            return
        }
        if let x = try? container.decode(EnabledEnum.self) {
            self = .enumeration(x)
            return
        }
        throw DecodingError.typeMismatch(EnabledUnion.self, DecodingError.Context(codingPath: decoder.codingPath, debugDescription: "Wrong type for EnabledUnion"))
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.singleValueContainer()
        switch self {
        case .bool(let x):
            try container.encode(x)
        case .enumeration(let x):
            try container.encode(x)
        }
    }
}

public enum EnabledEnum: String, Codable {
    case onDemand = "on_demand"
}

