/// Client → daemon request. ``id`` is required; notifications are not accepted.
// MARK: - RPCRequest
public struct RPCRequest: Codable {
    public let id: IDUnion
    public let jsonrpc: Jsonrpc
    public let method: String
    public let params: [String: JSONAny]?

    public enum CodingKeys: String, CodingKey {
        case id = "id"
        case jsonrpc = "jsonrpc"
        case method = "method"
        case params = "params"
    }

    public init(id: IDUnion, jsonrpc: Jsonrpc, method: String, params: [String: JSONAny]?) {
        self.id = id
        self.jsonrpc = jsonrpc
        self.method = method
        self.params = params
    }
}

public enum IDUnion: Codable {
    case integer(Int)
    case string(String)

    public init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let x = try? container.decode(Int.self) {
            self = .integer(x)
            return
        }
        if let x = try? container.decode(String.self) {
            self = .string(x)
            return
        }
        throw DecodingError.typeMismatch(IDUnion.self, DecodingError.Context(codingPath: decoder.codingPath, debugDescription: "Wrong type for IDUnion"))
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.singleValueContainer()
        switch self {
        case .integer(let x):
            try container.encode(x)
        case .string(let x):
            try container.encode(x)
        }
    }
}

